SINA_SMART["anat1-scapular"] = {"lecture":"anat1-scapular","title":"The scapular region and deltoid","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"anat1-scapular:e0","text":"Scapular spine → acromion (palpable).","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-scapular:e1","text":"Trapezius: CN XI; elevates shoulders, retracts scapula.","topic":"Superficial and deep muscles","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-scapular:e2","text":"Latissimus dorsi: thoracodorsal n.; adduction, medial rotation.","topic":"Superficial and deep muscles","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-scapular:e3","text":"Supraspinatus: abduction; infraspinatus: lateral rotation (suprascapular n.).","topic":"Superficial and deep muscles","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-scapular:e4","text":"Teres minor: lateral rotation (axillary n.); teres major: adduction, medial rotation.","topic":"Superficial and deep muscles","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-scapular:e5","text":"Rhomboids (dorsal scapular n.): retract; levator scapulae: elevates.","topic":"Superficial and deep muscles","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-scapular:e6","text":"Quadrangular space: axillary nerve + posterior circumflex humeral artery.","topic":"Spaces and deltoid","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-scapular:e7","text":"Triangular interval: radial nerve.","topic":"Spaces and deltoid","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-scapular:e8","text":"Deltoid: 3 parts → deltoid tuberosity; abduction; axillary n.","topic":"Spaces and deltoid","sec":2,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"16ls3f0":"a","j90r1w":"a","1er2a8k":"a","1n1cvz3":"a","lebsnl":"a","uzzxgg":"a","1f03gea":"a","8azwl0":"a","1rj886q":"a","f58l27":"a","1ezjyji":"a","epb13d":"a"},"mapCounts":{"verified":0,"auto":12,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"anat1-scapular:e0":{"s":0,"u":["Scapular spine → acromion (palpable).","The palpable spine of the scapula runs obliquely up and out to end in the acromion ."],"dp":[]},"anat1-scapular:e1":{"s":1,"u":["Trapezius: CN XI; elevates shoulders, retracts scapula.","Superficial : trapezius (external occipital protuberance, nuchal ligament, spines of T1-T12 → lateral third of clavicle, spine and acromion; elevates the shoulders and retracts the scapula; spinal accessory nerve, CN XI ) and latissimus dorsi (spines T7-T12, thoracolumbar fascia, iliac crest → bicipital groove of the humerus; adduction and medial rotation; thoracodorsal nerve )."],"dp":[{"h":"Clinical","t":"Accessory nerve (XI) injury in the posterior triangle: cannot shrug the shoulder; the scapula droops."}]},"anat1-scapular:e2":{"s":1,"u":["Latissimus dorsi: thoracodorsal n.; adduction, medial rotation.","Superficial : trapezius (external occipital protuberance, nuchal ligament, spines of T1-T12 → lateral third of clavicle, spine and acromion; elevates the shoulders and retracts the scapula; spinal accessory nerve, CN XI ) and latissimus dorsi (spines T7-T12, thoracolumbar fascia, iliac crest → bicipital groove of the humerus; adduction and medial rotation; thoracodorsal nerve ).","Deep : supraspinatus (supraspinous fossa → top of the greater tubercle; abduction; suprascapular nerve), infraspinatus (infraspinous fossa → greater tubercle; lateral rotation; suprascapular nerve), teres minor (lateral border → greater tubercle; lateral rotation; axillary nerve ), teres major (inferior angle → humerus medial to latissimus; adduction and medial rotation; lower subscapular nerve), rhomboids (spines C4-T4 → medial border; retract the scapula; dorsal scapular nerve), levator scapulae (transverse processes C1-C4 → superomedial angle; elevates the scapula)."],"dp":[]},"anat1-scapular:e3":{"s":1,"u":["Supraspinatus: abduction; infraspinatus: lateral rotation (suprascapular n.).","Deep : supraspinatus (supraspinous fossa → top of the greater tubercle; abduction; suprascapular nerve), infraspinatus (infraspinous fossa → greater tubercle; lateral rotation; suprascapular nerve), teres minor (lateral border → greater tubercle; lateral rotation; axillary nerve ), teres major (inferior angle → humerus medial to latissimus; adduction and medial rotation; lower subscapular nerve), rhomboids (spines C4-T4 → medial border; retract the scapula; dorsal scapular nerve), levator scapulae (transverse processes C1-C4 → superomedial angle; elevates the scapula)."],"dp":[]},"anat1-scapular:e4":{"s":1,"u":["Teres minor: lateral rotation (axillary n.); teres major: adduction, medial rotation.","Deep : supraspinatus (supraspinous fossa → top of the greater tubercle; abduction; suprascapular nerve), infraspinatus (infraspinous fossa → greater tubercle; lateral rotation; suprascapular nerve), teres minor (lateral border → greater tubercle; lateral rotation; axillary nerve ), teres major (inferior angle → humerus medial to latissimus; adduction and medial rotation; lower subscapular nerve), rhomboids (spines C4-T4 → medial border; retract the scapula; dorsal scapular nerve), levator scapulae (transverse processes C1-C4 → superomedial angle; elevates the scapula)."],"dp":[{"h":"Note","t":"Latissimus dorsi and teres major both adduct and medially rotate (the 'swimmer's' muscles); infraspinatus and teres minor laterally rotate ."}]},"anat1-scapular:e5":{"s":1,"u":["Rhomboids (dorsal scapular n.): retract; levator scapulae: elevates.","Deep : supraspinatus (supraspinous fossa → top of the greater tubercle; abduction; suprascapular nerve), infraspinatus (infraspinous fossa → greater tubercle; lateral rotation; suprascapular nerve), teres minor (lateral border → greater tubercle; lateral rotation; axillary nerve ), teres major (inferior angle → humerus medial to latissimus; adduction and medial rotation; lower subscapular nerve), rhomboids (spines C4-T4 → medial border; retract the scapula; dorsal scapular nerve), levator scapulae (transverse processes C1-C4 → superomedial angle; elevates the scapula)."],"dp":[{"h":"Note","t":"Nerves : trapezius = CN XI ; latissimus = thoracodorsal; supra- and infraspinatus = suprascapular ; teres minor and deltoid = axillary ; teres major = lower subscapular; rhomboids and levator = dorsal scapular ."}]},"anat1-scapular:e6":{"s":2,"u":["Quadrangular space: axillary nerve + posterior circumflex humeral artery.","Between teres minor (above) and teres major (below), the long head of triceps divides the gap into the lateral quadrangular (humerotricipital) space , carrying the axillary nerve and posterior circumflex humeral artery , and the medial triangular (omo-tricipital) space (circumflex scapular artery)."],"dp":[{"h":"Why a fractured humeral neck can numb the shoulder","t":"The axillary nerve leaves the quadrangular space and winds around the surgical neck of the humerus with the posterior circumflex humeral artery. A fracture or dislocation there can injure it, paralysing the deltoid (weak abduction) and numbing a patch of skin over the deltoid, the 'regimental badge' area, which clinicians test after shoulder trauma. Source: the lecture's quadrangular space and deltoid sections."},{"h":"Note","t":"Quadrangular space (teres minor, teres major, long head of triceps, humerus) = axillary nerve + posterior circumflex humeral artery . Triangular interval below teres major = radial nerve (+ profunda brachii)."}]},"anat1-scapular:e7":{"s":2,"u":["Triangular interval: radial nerve.","Below teres major, the triangular interval (humerotricipital fissure) transmits the radial nerve ."],"dp":[]},"anat1-scapular:e8":{"s":2,"u":["Deltoid: 3 parts → deltoid tuberosity; abduction; axillary n.","Deltoid : forms the rounded shoulder; clavicular (lateral third of clavicle), acromial and spinal parts → deltoid tuberosity ; main abductor of the shoulder; supplied by the axillary nerve."],"dp":[{"h":"Note","t":"Abduction : first 15° by supraspinatus , then deltoid to 90°, above that trapezius + serratus anterior rotate the scapula."},{"h":"Clinical","t":"Axillary nerve injury (surgical neck fracture, dislocation): deltoid wasting, weak abduction, numb 'regimental badge' patch over the deltoid."}]}},"meta":{"16ls3f0":{"a":"recall","vg":"anat1-scapular:e1/recall/1"},"j90r1w":{"a":"recall","vg":"anat1-scapular:e2/recall/1"},"1er2a8k":{"a":"recall","vg":"anat1-scapular:e8/recall/1"},"1n1cvz3":{"a":"recall","vg":"anat1-scapular:e3/recall/1"},"lebsnl":{"a":"recall","vg":"anat1-scapular:e4/recall/1"},"uzzxgg":{"a":"recall","vg":"anat1-scapular:e5/recall/1"},"1f03gea":{"a":"recall","vg":"anat1-scapular:e5/recall/2"},"8azwl0":{"a":"recall","vg":"anat1-scapular:e6/recall/1"},"1rj886q":{"a":"relationship","vg":"anat1-scapular:e6/relationship/1"},"f58l27":{"a":"recall","vg":"anat1-scapular:e7/recall/1"},"1ezjyji":{"a":"recall","vg":"anat1-scapular:e8/recall/2"},"epb13d":{"a":"recall","vg":"anat1-scapular:e8/recall/3"}},"explRev":"74e589aeabfd"};
